Lemma TAIL M5 model5 LK5 (fx5 : FPState) R5 :
  GM BX0 M5 model5 LK5 Aw cr ->
  PQATSS.binl_at RSEGS M5 o fb len v0 v1 ->
  getr R5 (reg 2) = Z_to_bv 64 spc -> getr R5 (reg 3) = getr R (reg 3) -> getr R5 (reg 4) = getr R (reg 4) -> getr R5 (reg 27) = getr R (reg 27) ->
  getr R5 (reg 8) = Z_to_bv 64 sp -> getr R5 (reg 18) = Z_to_bv 64 F -> getr R5 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 23) = Z_to_bv 64 F ->
  getr R5 (reg 19) = Z_to_bv 64 n -> getr R5 (reg 20) = Z_to_bv 64 o -> getr R5 (reg 21) = Z_to_bv 64 (o + 8) -> getr R5 (reg 24) = Z_to_bv 64 2147450880 ->
  getr R5 (reg 25) = Z_to_bv 64 (Z.of_nat len) -> getr R5 (reg 26) = Z_to_bv 64 ((o + 8) / 8 + 2147450880) ->
