(* [comment removed for export] *)
Lemma ENDP M4 model4 LK4 (fx4 fx5 : FPState) (R4 R5 : bvmap 5 word) (pc4 : Z) (M5v : mem) (fb' w0 w1 : Z) :
  mm M4 model4 LK4 ->
  PQATSS.binl_at RSEGS M4 o fb' lens w0 w1 -> PQATSS.binl_at RSEGS M4 s fbs lens s0 s1 ->
  fb' = PQATSC.asg_fb fb fbs lens -> w0 = PQATSC.asg_w0 d0 s0 lens -> w1 = PQATSC.asg_w1 d1 lend lens ->
  msteps RSEGS (L5SAR.st fx4 R4 pc4 (mrestrict (ahid Aw model4) M4)) (L5SAR.st fx5 R5 RET M5v) -> mem_grows (mrestrict (ahid Aw model4) M4) M5v ->
  (forall i, 0 <= i < 2 ^ 64 -> M5v (Z_to_bv 64 i) = mrestrict (ahid Aw model4) M4 (Z_to_bv 64 i)) ->
  (forall k, In k [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R5 (reg k) = getr R (reg k)) ->
  getr R5 (reg 1) = Z_to_bv 64 (bvu (getr R (reg 1))) -> getr R5 (reg 2) = Z_to_bv 64 sp ->
  getr R5 (reg 8) = Z_to_bv 64 (bvu (getr R (reg 8))) -> getr R5 (reg 9) = Z_to_bv 64 (bvu (getr R (reg 9))) -> getr R5 (reg 10) = Z_to_bv 64 o ->
  getr R5 (reg 18) = Z_to_bv 64 (bvu (getr R (reg 18))) -> getr R5 (reg 19) = Z_to_bv 64 (bvu (getr R (reg 19))) ->
  getr R5 (reg 20) = Z_to_bv 64 (bvu (getr R (reg 20))) -> getr R5 (reg 21) = Z_to_bv 64 (bvu (getr R (reg 21))) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 pc4 M4 model4) K.
