Lemma binl_mk (Mx : mem) x fbx (len : nat) w0 w1 :
  L5.u8_at RSEGS Mx x fbx -> 0 <= fbx < 256 -> Z.testbit fbx 0 = false -> L5.u64_at RSEGS Mx (x + 8) (Z.of_nat len) ->
  L5.u64_at RSEGS Mx (x + 16) w0 -> L5.u64_at RSEGS Mx (x + 24) w1 -> (len <= 2)%nat -> 0 <= w0 < 2 ^ 64 -> 0 <= w1 < 2 ^ 64 ->
  PQATSS.binl_at RSEGS Mx x fbx len w0 w1.
Proof.
