(* [comment removed for export] *)
Definition wc_ok (Wc : list L5.range) : Prop :=
  forall q, In q Wc -> (exists k, 32 <= k /\ k + 32 <= 504 /\ q = (F + k, 32)) \/ q = (o, 32) \/ q = (rr, 32).
(* [comment removed for export] *)
Lemma AFTER (Wc : list L5.range) M3 model3 LK3 (M4 : mem) model4 LK4 hc :
  GM BX0 M3 model3 LK3 Aw cr -> 0 <= hc -> hc + 1 <= PQATSC.DIV_H -> wc_ok Wc ->
  L5CA.ahpres L ar LBX FF' spc (PMSPA.pm_scr hc) Wc M3 M4 ->
  ri_inv HI LBX FF' LK4 cr Aw M4 (vml_of model4) -> L5CA.amodel_ok Aw model4 -> model_rt model3 model4 -> incl LK4 LK3 ->
  GM BX0 M4 model4 LK4 Aw cr
  /\ (forall a, spc <= a < sp -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a))
  /\ (forall a, F / 8 + 2147450880 <= a < F / 8 + 2147450880 + 64 -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a))
  /\ (forall a, (F + 32 <= a < F + 504) \/ (o <= a < o + 32) \/ (rr <= a < rr + 32) -> L5.outside Wc a -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a)).
Proof.
