Definition OBJP (MV : mem) (x : Z) : Prop :=
  (7036928 <= x <= 140737488355296 /\ PQATCP6.aligned x 8 /\ (2147446784 + 17592186048512 <= x \/ x + 32 <= 2147446784) /\ 0 <= x < 2 ^ 64)
  /\ (L5KA.zeros_at MV (x / 8 + 2147450880) 4 /\ L5.writable RSEGS MV x 32)
  /\ ((V2 - 352 + 368 <= x \/ x + 32 <= V2 - 352) /\ (x + 32 <= F \/ F + 512 <= x) /\ (x + 32 <= fl \/ fl + 1 <= x)
      /\ (x / 8 + 2147450880 + 4 <= F / 8 + 2147450880 \/ F / 8 + 2147450880 + 64 <= x / 8 + 2147450880)).
Lemma OBJP_of M1 model1 LK1 x : GM BX0 M1 model1 LK1 Aw cr -> PMSPA.aobjA FF x 32 -> x mod 8 = 0 -> PMSPA.accA M x 32 -> OBJP (mrestrict (ahid Aw model1) M1) x.
Proof.
