(* [comment removed for export] *)
Lemma CPDCALL M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 96) -> getr R3 (reg 11) = Z_to_bv 64 o -> shz M3 12 ->
  PQATSS.binl_at RSEGS M3 o fb 1%nat v0 v1 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 (fn : Z),
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 (F + 96) fn 1%nat v0 v1 -> Z.land fn 2 = Z.land fb 2 -> kept (inx (F + 96)) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
