(* [comment removed for export] *)
Lemma CMPCALL M3 model3 LK3 (fx3 : FPState) R3 (ra fn fd : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 96) -> getr R3 (reg 11) = Z_to_bv 64 (F + 32) -> shz M3 12 -> shz M3 4 ->
  PQATSS.binl_at RSEGS M3 (F + 96) fn 1%nat v0 v1 -> Z.testbit fn 1 = false ->
  PQATSS.binl_at RSEGS M3 (F + 32) fd 1%nat PQATSC.TEN19 d1 -> Z.testbit fd 1 = false ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 (PQATSC.cmp3 v0 PQATSC.TEN19) -> kept (fun _ => False) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
