Lemma rdn16 (M : mem) a v0 v1 : 0 <= a -> a + 16 <= 2 ^ 64 -> L5.u64_at RSEGS M a v0 -> L5.u64_at RSEGS M (a + 8) v1 ->
  rdn RSEGS M (Z_to_bv 64 a) (Z.to_nat 16) = Some (word_to_le_bytes 8 (Z_to_bv 64 v0) ++ word_to_le_bytes 8 (Z_to_bv 64 v1)).
Proof.
