Lemma u64_of_bytes2 (M : mem) a (bs : list byte) v0 v1 :
  bs = word_to_le_bytes 8 (Z_to_bv 64 v0) ++ word_to_le_bytes 8 (Z_to_bv 64 v1) -> 0 <= a -> a + 16 <= 2 ^ 64 ->
  (forall i, 0 <= i < 16 -> exists b, (nth_error bs (Z.to_nat i) = Some (Z_to_bv 8 b) /\ 0 <= b < 256) /\ byte_at M (a + i) b) ->
  L5.u64_at RSEGS M a v0 /\ L5.u64_at RSEGS M (a + 8) v1.
Proof.
