(* [comment removed for export] *)
Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r o s fb fbs : Z) (lend : nat) (d0 d1 pn s0 s1 : Z).
Local Notation W := ([(o, 32)] : list L5.range).
Local Notation SCR := (PMSPA.pm_scr PQATSC.ASG_H).
Local Notation SCR3 := (PMSPA.pm_scr 3).
Local Notation spc := (sp - 64).
Hypothesis HH : ri_inv HI LB FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PQATSC.ASG_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PQATSC.ASG_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis SP16 : sp mod 16 = 0.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 o.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 s.
Hypothesis AO : PMSPA.aobjA FF o 32.
Hypothesis O8 : o mod 8 = 0.
Hypothesis ACC : PMSPA.accA M o 32.
Hypothesis BIN : PQATSS.binl_at RSEGS M o fb lend d0 d1.
Hypothesis Hlend : (lend <= 1)%nat.
Hypothesis AOs : PMSPA.aobjA FF s 32.
Hypothesis S8 : s mod 8 = 0.
Hypothesis ACCs : PMSPA.accA M s 32.
Hypothesis BINs : PQATSW2.bdyn_at RSEGS M s fbs 2%nat pn s0 s1.
Hypothesis INP : In (pn, 64) LB.
Hypothesis APART : o + 32 <= s \/ s + 32 <= o.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe),
    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o ->
    PQATSS.binl_at RSEGS M' o (PQATSC.asg_fb fb fbs 2%nat) 2%nat s0 s1 -> PQATSW2.bdyn_at RSEGS M' s fbs 2%nat pn s0 s1 ->
    L5CA.ahpres L ar LB FF sp SCR W M M' ->
    model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
    ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

(* [comment removed for export] *)
Definition saves (Mx : mem) : Prop :=
  L5.u64_at RSEGS Mx (sp - 8) r /\ L5.u64_at RSEGS Mx (sp - 16) (bvu (getr R (reg 8))) /\ L5.u64_at RSEGS Mx (sp - 24) (bvu (getr R (reg 9)))
  /\ L5.u64_at RSEGS Mx (sp - 32) (bvu (getr R (reg 18))) /\ L5.u64_at RSEGS Mx (sp - 40) (bvu (getr R (reg 19)))
  /\ L5.u64_at RSEGS Mx (sp - 48) (bvu (getr R (reg 20))) /\ L5.u64_at RSEGS Mx (sp - 56) (bvu (getr R (reg 21))).
(* [comment removed for export] *)
Definition mm (M1 : mem) (model1 : Model) (LK1 : list fframe) : Prop :=
  ri_inv HI LB FF LK1 cr Aw M1 (vml_of model1) /\ L5CA.amodel_ok Aw model1 /\ model_rt model model1 /\ incl LK1 LK
  /\ L5SAR.ek L ar LB FF sp SCR W M M1 /\ L5SAR.dk L ar LB FF sp SCR M M1 /\ L5CA.astk ar M1 sp SCR /\ saves M1.

