Section Stmt.
Context {SCFG_P0 : ScfgP}.
Variables (segs : list Segment) (A : pm_addrs) (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Definition assign1d_specG (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r d s fb fbs : Z) (lend : nat) (d0 d1 pn s0 s1 : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 d -> getr R (reg 11) = Z_to_bv 64 s ->
    PMSPA.aobjA FF d 32 -> d mod 8 = 0 -> PMSPA.accA M d 32 -> PQATSS.binl_at segs M d fb lend d0 d1 -> (lend <= 1)%nat ->
    PMSPA.aobjA FF s 32 -> s mod 8 = 0 -> PMSPA.accA M s 32 -> PQATSW2.bdyn_at segs M s fbs 1%nat pn s0 s1 -> In (pn, 64) LB ->
    (d + 32 <= s \/ s + 32 <= d) ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 d ->
        PQATSS.binl_at segs M' d (PQATSC.asg_fb fb fbs 1%nat) 1%nat (PQATSC.asg_w0 d0 s0 1%nat) (PQATSC.asg_w1 d1 lend 1%nat) ->
        PQATSW2.bdyn_at segs M' s fbs 1%nat pn s0 s1 ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr h) [(d, 32)] M M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.
End Stmt.
Definition assign1d_spec {SCFG_P0 : ScfgP} (L : asan_layout) (ar : asan_run) (HI : asan_iface) : Prop :=
  assign1d_specG RSEGS PnLayoutA.ADDR_A L ar HI PQATSC.ASSIGN_A PQATSC.ASG_H.

